 final String[] QUAL={"trafikksikkerhet","avpassing","økning","komfort"};LinearLayout body;TextView status;Map<String,EditText> inputs=new HashMap<>();Map<String,String> ratings=new HashMap<>();int trip=1;String editId=null;JSONObject managedEdit=null;List<JSONObject> managed=new ArrayList<>();String manageKind="Turer";long lastSync=0;boolean syncing=false,adminBusy=false,authenticated=false,checkingLogin=false;TripDb db;Handler timer=new Handler(Looper.getMainLooper());String page="";Updates updates;Button updateButton;ScrollView scroll;TripTimer tripClock=new TripTimer();TextView clockView;Button clockStart,clockStop;long seenStopsVersion=0;boolean updatingStops=false;
