 public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(page.equals("form")){try{JSONObject draft=new JSONObject();for(Map.Entry<String,EditText> e:inputs.entrySet())draft.put(e.getKey(),e.getValue().getText().toString());for(String k:QUAL)draft.put(k,ratings.get(k));draft.put("trip",trip);if(editId!=null)draft.put("id",editId);if(managedEdit!=null)draft.put("_managed",managedEdit);out.putString("draft",draft.toString());}catch(Exception ignored){}}}
 public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==42&&results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)TimerService.show(this,"show");}
 public void onResume(){super.onResume();restoreClock();timer.removeCallbacks(clockTick);timer.post(clockTick);timer.post(tick);updateStatus();if(authenticated)updates.automatic();}
 public void onPause(){persistDraft();super.onPause();timer.removeCallbacks(tick);timer.removeCallbacks(clockTick);}
