 int boot(){return android.provider.Settings.Global.getInt(getContentResolver(),android.provider.Settings.Global.BOOT_COUNT,0);}
 long clockMillis(){return tripClock.elapsed(SystemClock.elapsedRealtime(),System.currentTimeMillis(),boot());}
 void restoreClock(){tripClock=TimerService.load(this);}
 void persistClock(){TimerService.store(this,tripClock);}
 void notificationTimer(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},42);TimerService.show(this,"show");}
 JSONObject draft()throws Exception{JSONObject d=new JSONObject();for(Map.Entry<String,EditText> e:inputs.entrySet())d.put(e.getKey(),e.getValue().getText().toString());for(String k:QUAL)d.put(k,ratings.get(k));d.put("trip",trip);if(editId!=null)d.put("id",editId);if(managedEdit!=null)d.put("_managed",managedEdit);return d;}
 void persistDraft(){if(!page.equals("form"))return;try{refreshStops();getSharedPreferences("draft",0).edit().putString("payload",draft().toString()).commit();}catch(Exception ignored){}}
 void refreshStops(){if(!page.equals("form")||!inputs.containsKey("stops"))return;android.content.SharedPreferences p=getSharedPreferences("draft",0);long version=p.getLong("stops_version",0);if(version==seenStopsVersion)return;try{JSONObject d=new JSONObject(p.getString("payload","{}"));updatingStops=true;inputs.get("stops").setText(d.optString("stops","0"));seenStopsVersion=version;}catch(Exception ignored){}finally{updatingStops=false;}}
 void manualStops(){if(updatingStops||!page.equals("form"))return;android.content.SharedPreferences p=getSharedPreferences("draft",0);seenStopsVersion=p.getLong("stops_version",0)+1;p.edit().putLong("stops_version",seenStopsVersion).commit();persistDraft();if(TimerService.active)TimerService.show(this,"show");}
 void addStop(){try{refreshStops();inputs.get("stops").setText(String.valueOf(StopCounter.next(inputs.get("stops").getText().toString())));}catch(Exception e){alert(e.getMessage());}}
 void clearDraft(){TimerService.dismiss(this);getSharedPreferences("trip_clock",0).edit().remove("completed").commit();page="";getSharedPreferences("draft",0).edit().clear().commit();tripClock.reset();persistClock();}
 void continueForm(){if(!requireLogin())return;persistDraft();try{String raw=getSharedPreferences("draft",0).getString("payload","");form(raw.isEmpty()?null:new JSONObject(raw));}catch(Exception e){alert(e.getMessage());}}
