 void navigation(View anchor){if(!requireLogin())return;persistDraft();PopupMenu menu=new PopupMenu(this,anchor);String[] labels={"Fortsett tur","Ny tur","Mine turer","Turer, kurs og biler","Innstillinger","Synkroniser nå","Sjekk oppdateringer"};for(int i=0;i<labels.length;i++)menu.getMenu().add(0,i,i,labels[i]);menu.setOnMenuItemClickListener(item->{switch(item.getItemId()){case 0:continueForm();break;case 1:newTrip();break;case 2:history();break;case 3:manageLoad();break;case 4:settings();break;case 5:sync();break;case 6:updates.check(true);break;}return true;});menu.show();}
