 void clockControls(){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setBackground(background(PANEL));card.setPadding(dp(14),dp(10),dp(14),dp(10));body.addView(card);card.addView(text("TIDTAKING",12,MUTED));clockView=text("00:00:00",32,TEAL);clockView.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);card.addView(clockView);LinearLayout row=new LinearLayout(this);card.addView(row);clockStart=button(row,"Start",()->startClock(),true);button(row,"Pause",()->{tripClock.stop(SystemClock.elapsedRealtime(),System.currentTimeMillis(),boot());persistClock();TimerService.show(this,"show");paintClock();},false);clockStop=button(row,"Stopp",()->stopClock(),false);button(card,"Nullstill klokke …",()->dialog().setTitle("Nullstill tidtaking?").setMessage("Den målte tiden slettes. Manuelt registrert tid beholdes.").setNegativeButton("Avbryt",null).setPositiveButton("Nullstill",(d,w)->{TimerService.dismiss(this);tripClock.reset();persistClock();paintClock();}).show(),false);card.addView(text("Start fyller inn dato og starttid. Stopp fyller inn forbrukt tid. Klokken fortsetter med skjermen av.",12,MUTED));}
 void startClock(){if(!requireLogin())return;if(tripClock.running)return;if(tripClock.accumulated==0){long now=System.currentTimeMillis();inputs.get("date").setText(new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date(now)));inputs.get("start_time").setText(new SimpleDateFormat("HH:mm",Locale.ROOT).format(new Date(now)));}tripClock.start(SystemClock.elapsedRealtime(),System.currentTimeMillis(),boot());persistClock();persistDraft();notificationTimer();paintClock();}
 void stopClock(){TimerService.dismiss(this);tripClock.stop(SystemClock.elapsedRealtime(),System.currentTimeMillis(),boot());persistClock();if(clockMillis()>0&&page.equals("form")){inputs.get("minutes").setText(String.format(Locale.ROOT,"%.4f",clockMillis()/60000.0));persistDraft();}paintClock();}
 void paintClock(){if(clockView==null||!page.equals("form"))return;clockView.setText(TripTimer.format(clockMillis()));clockStart.setEnabled(!tripClock.running);clockStart.setText(tripClock.accumulated>0?"Fortsett":"Start");clockStop.setEnabled(tripClock.running||tripClock.accumulated>0);}
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
