  e.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_dropdown_item_1line,new ArrayList<String>(names)));if(key.equals("course")){try{JSONArray courses=new JSONArray(getSharedPreferences("cloud",0).getString("course_setup","[]"));for(int i=0;i<courses.length();i++)names.add(courses.getJSONObject(i).getString("name"));e.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_dropdown_item_1line,new ArrayList<String>(names)));}catch(Exception ignored){}}e.setText(value);e.setOnClickListener(v->e.showDropDown());body.addView(e,new LinearLayout.LayoutParams(-1,-2));inputs.put(key,e);e.setCompoundDrawablesWithIntrinsicBounds(0,0,android.R.drawable.arrow_down_float,0);e.setOnTouchListener((v,event)->{if(event.getAction()==android.view.MotionEvent.ACTION_UP&&event.getX()>e.getWidth()-dp(56)){e.showDropDown();return true;}return false;});return e;
