  dropdown("driver","Sjåfør",saved==null?"":saved.optString("driver"));dropdown("course","Kurs",saved==null?prefs.getString("course",""):saved.optString("course"));dropdown("vehicle","Bil",saved==null?prefs.getString("vehicle",""):saved.optString("vehicle"));
  body.addView(text("Tur",14,MUTED));tripChoices=new LinearLayout(this);tripChoices.setOrientation(1);body.addView(tripChoices);paintTrips();inputs.get("course").addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){paintTrips();}public void afterTextChanged(android.text.Editable e){}});
  section("2 · Tid og målinger");body.addView(text("Du kan lagre med tomme felt. Skriv - for bevisst utelatt. Tom gjennomsnittsfart beregnes automatisk; notater er valgfrie.",13,MUTED));
  field("date","Dato (ÅÅÅÅ-MM-DD)",saved==null?new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date()):saved.optString("date"),false,false);field("start_time","Starttid (TT:MM)",saved==null?"":saved.optString("start_time"),false,false);
  field("minutes","Forbrukt tid (minutter eller mm:ss)",saved==null?"":saved.optString("minutes"),false,false);field("km","Kjørt (km)",saved==null?"":saved.optString("km"),true,false);field("liters","Drivstoff brukt totalt (liter)",saved==null?"":saved.optString("liters"),true,false);field("stops","Unødige stopp (kan skrives manuelt)",saved==null?"0":saved.optString("stops"),true,false);seenStopsVersion=getSharedPreferences("draft",0).getLong("stops_version",0);inputs.get("stops").addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){}public void afterTextChanged(android.text.Editable e){manualStops();}});Button add=button(body,"+ Unødig stans",()->addStop(),false);add.setBackground(background(Color.rgb(194,44,58)));add.setTextColor(Color.WHITE);
  field("average_speed","Gjennomsnitt km/t (tomt = beregnet)",saved==null?"":saved.optString("average_speed"),true,false);
  TextView consumption=text("Forbruk per 10 km: fyll inn liter og km",18,TEAL);body.addView(consumption);android.text.TextWatcher watch=new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){try{double km=Double.parseDouble(inputs.get("km").getText().toString().replace(',','.'));double liter=Double.parseDouble(inputs.get("liters").getText().toString().replace(',','.'));consumption.setText(km>0?String.format(Locale.getDefault(),"Forbruk per 10 km: %.2f liter",10*liter/km):"Legg inn distanse større enn null");}catch(Exception ignored){consumption.setText("Forbruk per 10 km: fyll inn liter og km");}}public void afterTextChanged(android.text.Editable e){}};inputs.get("km").addTextChangedListener(watch);inputs.get("liters").addTextChangedListener(watch);watch.onTextChanged("",0,0,0);
  section("3 · Vurdering");
  for(String k:QUAL){body.addView(text(k.equals("avpassing")?"Fartsavpassing":k.equals("økning")?"Fartsøkning":k.substring(0,1).toUpperCase()+k.substring(1),14,MUTED));ratings.put(k,saved==null?"":saved.optString(k,""));LinearLayout choices=new LinearLayout(this);body.addView(choices);Map<String,Button> buttons=new HashMap<>();for(String value:new String[]{"Bra","Middel","Svak","-"}){Button b=button(choices,value.equals("Middel")?"Middels":value,()->{ratings.put(k,value);for(Map.Entry<String,Button> item:buttons.entrySet()){item.getValue().setBackground(background(item.getKey().equals(value)?TEAL:PANEL));item.getValue().setTextColor(item.getKey().equals(value)?BG:TEXT);}},ratings.get(k).equals(value));buttons.put(value,b);}}
